163	<script>
164	(function(){
165	  var LAYOUT_KEY = 'coach888_layout';
166	
167	  function renumber(grid){
168	    grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
169	    var title = grid.previousElementSibling;
170	    if (title && title.classList.contains('section-title')) {
171	      var countEl = title.querySelector('.count');
172	      if (countEl) countEl.textContent = grid.querySelectorAll('.item').length + '項';
173	    }
174	  }
175	
176	  function saveLayout(){
177	    var layout = {};
178	    document.querySelectorAll('.grid').forEach(function(grid){
179	      layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
180	    });
181	    localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
182	    // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
183	    document.querySelectorAll('.grid').forEach(function(grid){
184	      localStorage.removeItem('coach888_order_' + grid.dataset.section);
185	    });
186	  }
187	
188	  function loadLayout(){
189	    var raw = localStorage.getItem(LAYOUT_KEY);
190	    if (raw) {
191	      try { return JSON.parse(raw); } catch(e){}
192	    }
193	    // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
194	    var legacy = {}, found = false;
195	    document.querySelectorAll('.grid').forEach(function(grid){
196	      var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
197	      if (old) {
198	        try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
199	      }
200	    });
201	    return found ? legacy : null;
202	  }
203	
204	  function applyLayout(){
205	    var layout = loadLayout();
206	    if (!layout) return;
207	    var allItems = {};
208	    document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
209	    document.querySelectorAll('.grid').forEach(function(grid){
210	      var ids = layout[grid.dataset.section];
211	      if (!ids) return;
212	      ids.forEach(function(id){
213	        if (allItems[id]) grid.appendChild(allItems[id]);
214	      });
215	    });
216	  }
217	
218	  function getDragAfterElement(grid, y){
219	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
220	    return els.reduce(function(closest, child){
221	      var box = child.getBoundingClientRect();
222	      var offset = y - box.top - box.height / 2;
223	      if (offset < 0 && offset > closest.offset) {
224	        return { offset: offset, element: child };
225	      }
226	      return closest;
227	    }, { offset: -Infinity, element: null }).element;
228	  }
229	
230	  // 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
231	  // .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
232	  // 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
233	  // 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
234	  // drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
235	  // 拖放機制，也就不會有這個衝突。
236	  var dragEl = null;
237	  var sourceGrid = null;
238	
239	  function onMouseMove(e){
240	    if (!dragEl) return;
241	    var el = document.elementFromPoint(e.clientX, e.clientY);
242	    var targetGrid = el ? el.closest('.grid') : null;
243	    if (!targetGrid) return;
244	    var afterEl = getDragAfterElement(targetGrid, e.clientY);
245	    if (afterEl == null) {
246	      targetGrid.appendChild(dragEl);
247	    } else if (afterEl !== dragEl) {
248	      targetGrid.insertBefore(dragEl, afterEl);
249	    }
250	  }
251	
252	  function onMouseUp(){
253	    if (!dragEl) return;
254	    dragEl.classList.remove('dragging');
255	    var targetGrid = dragEl.closest('.grid');
256	    renumber(sourceGrid);
257	    if (targetGrid !== sourceGrid) renumber(targetGrid);
258	    saveLayout();
259	    dragEl = null;
260	    sourceGrid = null;
261	    document.removeEventListener('mousemove', onMouseMove);
262	    document.removeEventListener('mouseup', onMouseUp);
263	  }
264	
265	  applyLayout();
266	
267	  document.querySelectorAll('.item').forEach(function(item){
268	    var handle = item.querySelector('.drag-handle');
269	    handle.addEventListener('mousedown', function(e){
270	      e.preventDefault();
271	      dragEl = item;
272	      sourceGrid = item.closest('.grid');
273	      item.classList.add('dragging');
274	      document.addEventListener('mousemove', onMouseMove);
275	      document.addEventListener('mouseup', onMouseUp);
276	    });
277	  });
278	
279	  document.querySelectorAll('.grid').forEach(renumber);
280	
281	  var toastEl = document.getElementById('toast');
282	  function toast(msg){
283	    toastEl.textContent = msg;
284	    toastEl.classList.add('show');
285	    setTimeout(function(){ toastEl.classList.remove('show'); }, 2200);
286	  }
287	
288	  document.getElementById('btnCopy').addEventListener('click', function(){
289	    var lines = [];
290	    document.querySelectorAll('.section-title').forEach(function(title, idx){
291	      var grid = document.querySelectorAll('.grid')[idx];
292	      lines.push(title.textContent.trim());
293	      grid.querySelectorAll('.item').forEach(function(item){
294	        var num = item.querySelector('.num').textContent;
295	        var name = item.querySelector('.name').textContent;
296	        var url = item.dataset.url;
297	        lines.push('  ' + num + '. ' + name + '  ' + url);
298	      });
299	      lines.push('');
300	    });
301	    var text = lines.join('\n');
302	    navigator.clipboard.writeText(text).then(function(){
303	      toast('已複製目前排序，貼給小龍蝦即可固化進正式檔案');
304	    }, function(){
305	      toast('複製失敗，請手動選取畫面上的文字');
306	    });
307	  });
308	})();
309	</script>
310	</body>
311	</html>
