1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>大樹AI作品總覽（個人專用）</title>
7	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@500;700;900&display=swap" rel="stylesheet">
8	<style>
9	  :root { --gold:#c8a96e; --dark:#0a0a0a; --dark2:#141414; --line:rgba(200,169,110,.3); }
10	  * { margin:0; padding:0; box-sizing:border-box; }
11	  body { font-family:'Noto Sans TC', sans-serif; background:var(--dark); color:#fff; padding:36px 20px 100px; }
12	  .wrap { max-width:920px; margin:0 auto; }
13	  h1 { font-size:30px; font-weight:900; margin-bottom:6px; }
14	  h1 span { color:var(--gold); }
15	  .sub { color:rgba(255,255,255,.5); font-size:16px; margin-bottom:18px; }
16	  .toolbar { display:flex; gap:12px; align-items:center; margin-bottom:28px; flex-wrap:wrap; }
17	  .btn-copy {
18	    background:rgba(200,169,110,.12); border:1px solid var(--gold); color:var(--gold);
19	    font-family:inherit; font-size:14px; font-weight:900; padding:10px 18px; border-radius:10px;
20	    cursor:pointer; transition:.2s;
21	  }
22	  .btn-copy:hover { background:rgba(200,169,110,.25); }
23	  .toast {
24	    position:fixed; bottom:28px; left:50%; transform:translateX(-50%) translateY(20px);
25	    background:var(--gold); color:#151107; font-weight:900; font-size:15px;
26	    padding:14px 28px; border-radius:12px; opacity:0; pointer-events:none;
27	    transition:.25s; z-index:999; box-shadow:0 8px 24px rgba(0,0,0,.4);
28	  }
29	  .toast.show { opacity:1; transform:translateX(-50%) translateY(0); }
30	  .section-title {
31	    display:flex; align-items:center; gap:12px; margin:40px 0 16px;
32	    font-size:20px; font-weight:900; color:var(--gold);
33	  }
34	  .section-title .count { font-size:14px; color:rgba(255,255,255,.4); font-weight:700; }
35	  .section-title::after { content:''; flex:1; height:1px; background:var(--line); }
36	  .grid { display:flex; flex-direction:column; gap:8px; }
37	  .item {
38	    display:flex; align-items:center; gap:12px; color:#fff;
39	    background:var(--dark2); border:1px solid var(--line); border-radius:10px;
40	    padding:10px 14px 10px 8px; transition:border-color .2s, background .2s;
41	  }
42	  .item:hover { border-color:var(--gold); background:#1a1a1a; }
43	  .item.dragging { opacity:.35; border-style:dashed; }
44	  .drag-handle {
45	    flex-shrink:0; width:28px; height:34px; display:flex; align-items:center; justify-content:center;
46	    color:rgba(255,255,255,.3); cursor:grab; font-size:18px; letter-spacing:-2px; touch-action:none;
47	    border-radius:6px; transition:.2s;
48	  }
49	  .drag-handle:hover { color:var(--gold); background:rgba(200,169,110,.1); }
50	  .drag-handle:active { cursor:grabbing; }
51	  .num {
52	    flex-shrink:0; width:34px; height:34px; border-radius:8px; background:#1c1c1c;
53	    display:flex; align-items:center; justify-content:center; font-weight:900;
54	    font-size:15px; color:var(--gold); border:1px solid var(--line);
55	  }
56	  .name { font-weight:700; font-size:17px; flex:1; color:#fff; text-decoration:none; }
57	  .name:hover { text-decoration:underline; }
58	  .url { font-size:13px; color:rgba(255,255,255,.35); font-variant-numeric:tabular-nums; }
59	  .badge {
60	    font-size:12px; font-weight:900; padding:3px 9px; border-radius:999px; flex-shrink:0;
61	  }
62	  .badge.public { background:rgba(6,199,85,.15); color:#06C755; }
63	  .badge.reserved { background:rgba(200,169,110,.15); color:var(--gold); }
64	  .badge.private { background:rgba(255,255,255,.08); color:rgba(255,255,255,.5); }
65	  .badge.pending { background:rgba(220,80,80,.15); color:#ff8a8a; }
66	  .badge.tool { background:rgba(100,170,255,.15); color:#7cb4ff; }
67	  .badge.star { background:rgba(200,169,110,.25); color:var(--gold); }
68	  .badge.backend { background:rgba(124,180,255,.18); color:#7cb4ff; }
69	  .note { font-size:13px; color:rgba(255,255,255,.4); padding:10px 18px; }
70	  .title-text, .badge { cursor:text; }
71	  .title-text:focus, .badge:focus { outline:1px dashed var(--gold); border-radius:4px; }
72	  @media (max-width:520px){
73	    .url { display:none; }
74	    .name { font-size:15px; }
75	  }
76	</style>
77	</head>
78	<body>
