159	      <div class="item" data-url="https://chapters.bymyway.com/admin"><span class="drag-handle">⠿</span><div class="num">14</div><a class="name" href="https://chapters.bymyway.com/admin" target="_blank">BNI｜大台南南區分會後台管理系統</a><div class="url">chapters.bymyway.com/admin</div><div class="badge private" contenteditable="true" spellcheck="false">私藏·BNI</div></div>
160	    </div>
161	  </div>
162	
163	  <div class="toast" id="toast"></div>
164	
165	<script>
166	(function(){
167	  var LAYOUT_KEY = 'coach888_layout';
168	  var TITLES_KEY = 'coach888_titles';
169	  var BADGES_KEY = 'coach888_badges';
170	
171	  function renumber(grid){
172	    grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
173	    var title = grid.previousElementSibling;
174	    if (title && title.classList.contains('section-title')) {
175	      var countEl = title.querySelector('.count');
176	      if (countEl) countEl.textContent = grid.querySelectorAll('.item').length + '項';
177	    }
178	  }
179	
180	  function saveLayout(){
181	    var layout = {};
182	    document.querySelectorAll('.grid').forEach(function(grid){
183	      layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
184	    });
185	    localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
186	    // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
187	    document.querySelectorAll('.grid').forEach(function(grid){
188	      localStorage.removeItem('coach888_order_' + grid.dataset.section);
189	    });
190	  }
191	
192	  function loadLayout(){
193	    var raw = localStorage.getItem(LAYOUT_KEY);
194	    if (raw) {
195	      try { return JSON.parse(raw); } catch(e){}
196	    }
197	    // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
198	    var legacy = {}, found = false;
199	    document.querySelectorAll('.grid').forEach(function(grid){
200	      var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
201	      if (old) {
202	        try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
203	      }
204	    });
205	    return found ? legacy : null;
206	  }
207	
208	  function saveTitles(){
209	    var titles = {};
210	    document.querySelectorAll('.section-title').forEach(function(t){
211	      var span = t.querySelector('.title-text');
212	      if (span) titles[t.dataset.section] = span.textContent.trim();
213	    });
214	    localStorage.setItem(TITLES_KEY, JSON.stringify(titles));
215	  }
216	
217	  function applyTitles(){
218	    var raw = localStorage.getItem(TITLES_KEY);
219	    if (!raw) return;
220	    try {
221	      var titles = JSON.parse(raw);
222	      document.querySelectorAll('.section-title').forEach(function(t){
223	        var span = t.querySelector('.title-text');
224	        if (span && titles[t.dataset.section] != null) span.textContent = titles[t.dataset.section];
225	      });
226	    } catch(e){}
227	  }
228	
229	  function saveBadges(){
230	    var badges = {};
231	    document.querySelectorAll('.item').forEach(function(it){
232	      var b = it.querySelector('.badge');
233	      if (b) badges[it.dataset.url] = b.textContent.trim();
234	    });
235	    localStorage.setItem(BADGES_KEY, JSON.stringify(badges));
236	  }
237	
238	  function applyBadges(){
239	    var raw = localStorage.getItem(BADGES_KEY);
240	    if (!raw) return;
241	    try {
242	      var badges = JSON.parse(raw);
243	      document.querySelectorAll('.item').forEach(function(it){
244	        var b = it.querySelector('.badge');
245	        if (b && badges[it.dataset.url] != null) b.textContent = badges[it.dataset.url];
246	      });
247	    } catch(e){}
248	  }
249	
250	  function bindEditable(el, onSave){
251	    el.addEventListener('keydown', function(e){
252	      if (e.key === 'Enter') { e.preventDefault(); el.blur(); }
253	    });
254	    el.addEventListener('blur', onSave);
255	  }
256	
257	  function applyLayout(){
258	    var layout = loadLayout();
259	    if (!layout) return;
260	    var allItems = {};
261	    document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
262	    document.querySelectorAll('.grid').forEach(function(grid){
263	      var ids = layout[grid.dataset.section];
264	      if (!ids) return;
265	      ids.forEach(function(id){
266	        if (allItems[id]) grid.appendChild(allItems[id]);
267	      });
268	    });
269	  }
270	
271	  function getDragAfterElement(grid, y){
272	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
273	    return els.reduce(function(closest, child){
274	      var box = child.getBoundingClientRect();
275	      var offset = y - box.top - box.height / 2;
276	      if (offset < 0 && offset > closest.offset) {
277	        return { offset: offset, element: child };
278	      }
279	      return closest;
280	    }, { offset: -Infinity, element: null }).element;
281	  }
282	
283	  // 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
284	  // .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
285	  // 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
286	  // 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
287	  // drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
288	  // 拖放機制，也就不會有這個衝突。
289	  var dragEl = null;
290	  var sourceGrid = null;
291	
292	  function onMouseMove(e){
293	    if (!dragEl) return;
294	    var el = document.elementFromPoint(e.clientX, e.clientY);
295	    var targetGrid = el ? el.closest('.grid') : null;
296	    if (!targetGrid) return;
297	    var afterEl = getDragAfterElement(targetGrid, e.clientY);
298	    if (afterEl == null) {
299	      targetGrid.appendChild(dragEl);
300	    } else if (afterEl !== dragEl) {
301	      targetGrid.insertBefore(dragEl, afterEl);
302	    }
303	  }
304	
305	  function onMouseUp(){
306	    if (!dragEl) return;
307	    dragEl.classList.remove('dragging');
308	    var targetGrid = dragEl.closest('.grid');
309	    renumber(sourceGrid);
310	    if (targetGrid !== sourceGrid) renumber(targetGrid);
311	    saveLayout();
312	    dragEl = null;
313	    sourceGrid = null;
314	    document.removeEventListener('mousemove', onMouseMove);
315	    document.removeEventListener('mouseup', onMouseUp);
316	  }
317	
318	  applyLayout();
319	  applyTitles();
320	  applyBadges();
321	
322	  document.querySelectorAll('.item').forEach(function(item){
323	    var handle = item.querySelector('.drag-handle');
324	    handle.addEventListener('mousedown', function(e){
325	      e.preventDefault();
326	      dragEl = item;
327	      sourceGrid = item.closest('.grid');
328	      item.classList.add('dragging');
329	      document.addEventListener('mousemove', onMouseMove);
330	      document.addEventListener('mouseup', onMouseUp);
331	    });
332	  });
333	
334	  document.querySelectorAll('.title-text').forEach(function(el){ bindEditable(el, saveTitles); });
335	  document.querySelectorAll('.badge').forEach(function(el){ bindEditable(el, saveBadges); });
336	
337	  document.querySelectorAll('.grid').forEach(renumber);
338	
339	  var toastEl = document.getElementById('toast');
340	  function toast(msg){
341	    toastEl.textContent = msg;
342	    toastEl.classList.add('show');
343	    setTimeout(function(){ toastEl.classList.remove('show'); }, 2200);
344	  }
345	
346	  document.getElementById('btnCopy').addEventListener('click', function(){
347	    var lines = [];
348	    document.querySelectorAll('.section-title').forEach(function(title, idx){
349	      var grid = document.querySelectorAll('.grid')[idx];
350	      lines.push(title.textContent.trim());
351	      grid.querySelectorAll('.item').forEach(function(item){
352	        var num = item.querySelector('.num').textContent;
353	        var name = item.querySelector('.name').textContent;
354	        var url = item.dataset.url;
355	        var badge = item.querySelector('.badge').textContent.trim();
356	        lines.push('  ' + num + '. ' + name + '  ' + url + '  [' + badge + ']');
357	      });
358	      lines.push('');
359	    });
360	    var text = lines.join('\n');
361	    navigator.clipboard.writeText(text).then(function(){
362	      toast('已複製目前排序，貼給小龍蝦即可固化進正式檔案');
363	    }, function(){
364	      toast('複製失敗，請手動選取畫面上的文字');
365	    });
366	  });
367	})();
368	</script>
369	</body>
370	</html>
