1	<!DOCTYPE html>
2	<html lang="zh-Hant">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>大樹AI作品總覽（個人專用）</title>
7	<link href="https://fonts.googleapis.com/css2?family=Noto+Sans+TC:wght@500;700;900&display=swap" rel="stylesheet">
8	<style>
9	  :root { --gold:#c8a96e; --dark:#0a0a0a; --dark2:#141414; --line:rgba(200,169,110,.3); }
10	  * { margin:0; padding:0; box-sizing:border-box; }
11	  body { font-family:'Noto Sans TC', sans-serif; background:var(--dark); color:#fff; padding:36px 20px 100px; }
12	  .wrap { max-width:1500px; margin:0 auto; }
13	  .row { display:grid; grid-template-columns:1fr 1fr; column-gap:48px; }
14	  .col { min-width:0; }
15	  @media (max-width:900px){
16	    .row { grid-template-columns:1fr; }
17	  }
18	  h1 { font-size:30px; font-weight:900; margin-bottom:6px; }
19	  h1 span { color:var(--gold); }
20	  .sub { color:rgba(255,255,255,.5); font-size:16px; margin-bottom:18px; }
21	  .toolbar { display:flex; gap:12px; align-items:center; margin-bottom:28px; flex-wrap:wrap; }
22	  .btn-copy {
23	    background:rgba(200,169,110,.12); border:1px solid var(--gold); color:var(--gold);
24	    font-family:inherit; font-size:14px; font-weight:900; padding:10px 18px; border-radius:10px;
25	    cursor:pointer; transition:.2s;
26	  }
27	  .btn-copy:hover { background:rgba(200,169,110,.25); }
28	  .toast {
29	    position:fixed; bottom:28px; left:50%; transform:translateX(-50%) translateY(20px);
30	    background:var(--gold); color:#151107; font-weight:900; font-size:15px;
31	    padding:14px 28px; border-radius:12px; opacity:0; pointer-events:none;
32	    transition:.25s; z-index:999; box-shadow:0 8px 24px rgba(0,0,0,.4);
33	  }
34	  .toast.show { opacity:1; transform:translateX(-50%) translateY(0); }
35	  .section-title {
36	    display:flex; align-items:center; gap:12px; margin:40px 0 16px;
37	    font-size:20px; font-weight:900; color:var(--gold);
38	  }
39	  .section-title .count { font-size:14px; color:rgba(255,255,255,.4); font-weight:700; }
40	  .section-title::after { content:''; flex:1; height:1px; background:var(--line); }
41	  .grid { display:flex; flex-direction:column; gap:8px; }
42	  .item {
43	    display:flex; align-items:center; gap:12px; color:#fff;
44	    background:var(--dark2); border:1px solid var(--line); border-radius:10px;
45	    padding:10px 14px 10px 8px; transition:border-color .2s, background .2s;
46	  }
47	  .item:hover { border-color:var(--gold); background:#1a1a1a; }
48	  .item.dragging { opacity:.35; border-style:dashed; }
49	  .drag-handle {
50	    flex-shrink:0; width:28px; height:34px; display:flex; align-items:center; justify-content:center;
51	    color:rgba(255,255,255,.3); cursor:grab; font-size:18px; letter-spacing:-2px; touch-action:none;
