188	<script>
189	(function(){
190	  var LAYOUT_KEY = 'coach888_layout';
191	  var TITLES_KEY = 'coach888_titles';
192	  var BADGES_KEY = 'coach888_badges';
193	
194	  function renumber(grid){
195	    grid.querySelectorAll('.item .num').forEach(function(el, i){ el.textContent = i + 1; });
196	    var title = grid.previousElementSibling;
197	    if (title && title.classList.contains('section-title')) {
198	      var countEl = title.querySelector('.count');
199	      if (countEl) countEl.textContent = grid.querySelectorAll('.item').length + '項';
200	    }
201	  }
202	
203	  function saveLayout(){
204	    var layout = {};
205	    document.querySelectorAll('.grid').forEach(function(grid){
206	      layout[grid.dataset.section] = Array.prototype.map.call(grid.querySelectorAll('.item'), function(it){ return it.dataset.url; });
207	    });
208	    localStorage.setItem(LAYOUT_KEY, JSON.stringify(layout));
209	    // 清掉2026-07-20版之前的舊格式（每組各自存一個key），避免新舊格式打架
210	    document.querySelectorAll('.grid').forEach(function(grid){
211	      localStorage.removeItem('coach888_order_' + grid.dataset.section);
212	    });
213	  }
214	
215	  function loadLayout(){
216	    var raw = localStorage.getItem(LAYOUT_KEY);
217	    if (raw) {
218	      try { return JSON.parse(raw); } catch(e){}
219	    }
220	    // 相容舊版：只支援組內排序、每組各自一個key，讀出來當初始佈局
221	    var legacy = {}, found = false;
222	    document.querySelectorAll('.grid').forEach(function(grid){
223	      var old = localStorage.getItem('coach888_order_' + grid.dataset.section);
224	      if (old) {
225	        try { legacy[grid.dataset.section] = JSON.parse(old); found = true; } catch(e){}
226	      }
227	    });
228	    return found ? legacy : null;
229	  }
230	
231	  function saveTitles(){
232	    var titles = {};
233	    document.querySelectorAll('.section-title').forEach(function(t){
234	      var span = t.querySelector('.title-text');
235	      if (span) titles[t.dataset.section] = span.textContent.trim();
236	    });
237	    localStorage.setItem(TITLES_KEY, JSON.stringify(titles));
238	  }
239	
240	  function applyTitles(){
241	    var raw = localStorage.getItem(TITLES_KEY);
242	    if (!raw) return;
243	    try {
244	      var titles = JSON.parse(raw);
245	      document.querySelectorAll('.section-title').forEach(function(t){
246	        var span = t.querySelector('.title-text');
247	        if (span && titles[t.dataset.section] != null) span.textContent = titles[t.dataset.section];
248	      });
249	    } catch(e){}
250	  }
251	
252	  function saveBadges(){
253	    var badges = {};
254	    document.querySelectorAll('.item').forEach(function(it){
255	      var b = it.querySelector('.badge');
256	      if (b) badges[it.dataset.url] = b.textContent.trim();
257	    });
258	    localStorage.setItem(BADGES_KEY, JSON.stringify(badges));
259	  }
260	
261	  function applyBadges(){
262	    var raw = localStorage.getItem(BADGES_KEY);
263	    if (!raw) return;
264	    try {
265	      var badges = JSON.parse(raw);
266	      document.querySelectorAll('.item').forEach(function(it){
267	        var b = it.querySelector('.badge');
268	        if (b && badges[it.dataset.url] != null) b.textContent = badges[it.dataset.url];
269	      });
270	    } catch(e){}
271	  }
272	
273	  function bindEditable(el, onSave){
274	    el.addEventListener('keydown', function(e){
275	      if (e.key === 'Enter') { e.preventDefault(); el.blur(); }
276	    });
277	    el.addEventListener('blur', onSave);
278	  }
279	
280	  function applyLayout(){
281	    var layout = loadLayout();
282	    if (!layout) return;
283	    var allItems = {};
284	    document.querySelectorAll('.item').forEach(function(it){ allItems[it.dataset.url] = it; });
285	    document.querySelectorAll('.grid').forEach(function(grid){
286	      var ids = layout[grid.dataset.section];
287	      if (!ids) return;
288	      ids.forEach(function(id){
289	        if (allItems[id]) grid.appendChild(allItems[id]);
290	      });
291	    });
292	  }
293	
294	  function getDragAfterElement(grid, y){
295	    var els = Array.prototype.slice.call(grid.querySelectorAll('.item:not(.dragging)'));
296	    return els.reduce(function(closest, child){
297	      var box = child.getBoundingClientRect();
298	      var offset = y - box.top - box.height / 2;
299	      if (offset < 0 && offset > closest.offset) {
300	        return { offset: offset, element: child };
301	      }
302	      return closest;
303	    }, { offset: -Infinity, element: null }).element;
304	  }
305	
306	  // 2026-07-20 改用滑鼠事件手刻拖曳（不用 HTML5 原生 draggable API）：
307	  // .item 內部有 <a class="name" href="..."> 連結，瀏覽器對連結元素有自己的
308	  // 原生拖曳行為，跟外層 draggable="true" 互相打架，導致放開時被瀏覽器判定
309	  // 為無效拖放而彈回原位（教練實測回報「都會被打回原來的位置」）。改成監聽
310	  // drag-handle 的 mousedown/mousemove/mouseup 手動搬移 DOM，完全不觸發原生
311	  // 拖放機制，也就不會有這個衝突。
312	  var dragEl = null;
313	  var sourceGrid = null;
314	
315	  function onMouseMove(e){
316	    if (!dragEl) return;
317	    var el = document.elementFromPoint(e.clientX, e.clientY);
318	    var targetGrid = el ? el.closest('.grid') : null;
319	    if (!targetGrid) return;
320	    var afterEl = getDragAfterElement(targetGrid, e.clientY);
321	    if (afterEl == null) {
322	      targetGrid.appendChild(dragEl);
323	    } else if (afterEl !== dragEl) {
324	      targetGrid.insertBefore(dragEl, afterEl);
325	    }
326	  }
327	
328	  function onMouseUp(){
329	    if (!dragEl) return;
330	    dragEl.classList.remove('dragging');
331	    var targetGrid = dragEl.closest('.grid');
332	    renumber(sourceGrid);
333	    if (targetGrid !== sourceGrid) renumber(targetGrid);
334	    saveLayout();
335	    dragEl = null;
336	    sourceGrid = null;
337	    document.removeEventListener('mousemove', onMouseMove);
338	    document.removeEventListener('mouseup', onMouseUp);
339	  }
340	
341	  applyLayout();
342	  applyTitles();
343	  applyBadges();
344	
345	  document.querySelectorAll('.item').forEach(function(item){
346	    var handle = item.querySelector('.drag-handle');
347	    handle.addEventListener('mousedown', function(e){
348	      e.preventDefault();
349	      dragEl = item;
350	      sourceGrid = item.closest('.grid');
351	      item.classList.add('dragging');
352	      document.addEventListener('mousemove', onMouseMove);
353	      document.addEventListener('mouseup', onMouseUp);
354	    });
355	  });
356	
357	  document.querySelectorAll('.title-text').forEach(function(el){ bindEditable(el, saveTitles); });
358	  document.querySelectorAll('.badge').forEach(function(el){ bindEditable(el, saveBadges); });
359	
360	  document.querySelectorAll('.grid').forEach(renumber);
361	
362	  var toastEl = document.getElementById('toast');
363	  function toast(msg){
364	    toastEl.textContent = msg;
365	    toastEl.classList.add('show');
366	    setTimeout(function(){ toastEl.classList.remove('show'); }, 2200);
367	  }
368	
369	  document.getElementById('btnCopy').addEventListener('click', function(){
370	    var lines = [];
371	    document.querySelectorAll('.section-title').forEach(function(title, idx){
372	      var grid = document.querySelectorAll('.grid')[idx];
373	      lines.push(title.textContent.trim());
374	      grid.querySelectorAll('.item').forEach(function(item){
375	        var num = item.querySelector('.num').textContent;
376	        var name = item.querySelector('.name').textContent;
377	        var url = item.dataset.url;
378	        var badge = item.querySelector('.badge').textContent.trim();
379	        lines.push('  ' + num + '. ' + name + '  ' + url + '  [' + badge + ']');
380	      });
381	      lines.push('');
382	    });
383	    var text = lines.join('\n');
384	    navigator.clipboard.writeText(text).then(function(){
385	      toast('已複製目前排序，貼給小龍蝦即可固化進正式檔案');
386	    }, function(){
387	      toast('複製失敗，請手動選取畫面上的文字');
388	    });
389	  });
390	})();
391	</script>
392	</body>
393	</html>
