var rows = document.querySelectorAll('.row');
var out = [];
rows.forEach(function(row){
  var cols = row.querySelectorAll(':scope > .col');
  var pair = [];
  cols.forEach(function(col){
    var t = col.querySelector('.title-text');
    var rect = col.getBoundingClientRect();
    pair.push({title: t ? t.textContent : null, left: Math.round(rect.left), top: Math.round(rect.top)});
  });
  out.push(pair);
});
JSON.stringify({rows: out, itemCount: document.querySelectorAll('.item').length});

